// GENERATED by scripts/gen-version.mjs from CHANGELOG.md and package.json — do not edit.
// Add a release by adding a heading to CHANGELOG.md and bumping package.json; the build fails
// if those two disagree, so this file cannot drift from either.

/** One released version of Loft, as `CHANGELOG.md` describes it. */
export interface Release {
  version: string;
  /** ISO date the release reached production. */
  date: string;
  /** The entry's markdown body, kept whole so a check can read it as written. */
  body: string;
  /** That body's structure, resolved at build time so the route renders data, not markdown. */
  sections: readonly Section[];
}

/** One `### Heading` block of a release entry. */
export interface Section {
  heading: string;
  /** Prose before the first bullet, where the entry has any. */
  lead: string;
  /** Bullets, each still carrying inline markdown for `lib/inline-markdown.tsx`. */
  items: readonly string[];
}

/** The version the app is running, shown in the footer on every route. */
export const VERSION = "0.9.0";

/** The date that version reached production. */
export const RELEASED = "2026-08-03";

